create extension if not exists pgcrypto;
alter table public.chat_lists add column if not exists folder_type text not null default 'custom', add column if not exists color text not null default '#64748b';
alter table public.chat_lists drop constraint if exists chat_lists_folder_type_check;
alter table public.chat_lists add constraint chat_lists_folder_type_check check(folder_type in ('custom','personal','work'));
create unique index if not exists chat_lists_one_system_folder_per_type on public.chat_lists(user_id,folder_type) where folder_type in ('personal','work');
create table if not exists public.user_conversation_labels(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(btrim(name)) between 1 and 48),color text not null default '#64748b' check(color ~ '^#[0-9A-Fa-f]{6}$'),icon text not null default 'tag',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id),unique(user_id,name));
create table if not exists public.user_conversation_label_items(user_id uuid not null references auth.users(id) on delete cascade,label_id uuid not null,conversation_id uuid not null references public.conversations(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,label_id,conversation_id),foreign key(label_id,user_id) references public.user_conversation_labels(id,user_id) on delete cascade);
create table if not exists public.user_conversation_classifications(user_id uuid not null references auth.users(id) on delete cascade,conversation_id uuid not null references public.conversations(id) on delete cascade,category text not null check(category in ('personal','work')),source text not null default 'manual' check(source in ('manual','automatic')),updated_at timestamptz not null default now(),primary key(user_id,conversation_id));
create table if not exists public.user_classification_rules(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(btrim(name)) between 1 and 80),enabled boolean not null default true,priority integer not null default 100,conditions jsonb not null default '{}'::jsonb check(jsonb_typeof(conditions)='object'),action jsonb not null default '{}'::jsonb check(jsonb_typeof(action)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.private_conversation_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,conversation_id uuid not null references public.conversations(id) on delete cascade,note text not null default '' check(length(note)<=10000),order_status text not null default 'none' check(order_status in ('none','new','in_progress','awaiting_payment','paid','shipped','completed','cancelled')),financial_amount numeric(14,2) check(financial_amount is null or financial_amount>=0),currency text not null default 'SAR' check(currency ~ '^[A-Z]{3}$'),follow_up_at timestamptz,responsible_user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.conversation_documents(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,conversation_id uuid not null references public.conversations(id) on delete cascade,storage_path text not null unique,file_name text not null check(length(btrim(file_name)) between 1 and 240),mime_type text not null check(mime_type in ('application/pdf','image/jpeg','image/png','image/webp')),size_bytes bigint not null check(size_bytes>0 and size_bytes<=26214400),visibility text not null default 'private' check(visibility in ('private','shared')),created_at timestamptz not null default now(),shared_at timestamptz);
create table if not exists public.private_reply_contexts(direct_message_id uuid primary key references public.chat_messages(id) on delete cascade,direct_conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,source_conversation_id uuid not null references public.conversations(id) on delete cascade,source_message_id uuid not null references public.chat_messages(id) on delete cascade,quoted_content text not null check(length(quoted_content)<=1200),quoted_sender_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),constraint private_reply_not_same_conversation check(direct_conversation_id<>source_conversation_id));
alter table public.user_conversation_labels enable row level security;
alter table public.user_conversation_label_items enable row level security;
alter table public.user_conversation_classifications enable row level security;
alter table public.user_classification_rules enable row level security;
alter table public.private_conversation_notes enable row level security;
alter table public.conversation_documents enable row level security;
alter table public.private_reply_contexts enable row level security;
grant select,insert,update,delete on public.user_conversation_labels,public.user_conversation_label_items,public.user_conversation_classifications,public.user_classification_rules,public.private_conversation_notes,public.conversation_documents to authenticated;
grant select,insert on public.private_reply_contexts to authenticated;
create policy "Users manage their own conversation labels" on public.user_conversation_labels for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "Users manage labels on their conversations" on public.user_conversation_label_items for all to authenticated using(user_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id)) with check(user_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id) and exists(select 1 from public.user_conversation_labels l where l.id=label_id and l.user_id=(select auth.uid())));
create policy "Users manage their conversation classifications" on public.user_conversation_classifications for all to authenticated using(user_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id)) with check(user_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id));
create policy "Users manage their classification rules" on public.user_classification_rules for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "Users manage their private conversation notes" on public.private_conversation_notes for all to authenticated using(user_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id)) with check(user_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id));
create policy "Owners and conversation members read shared documents" on public.conversation_documents for select to authenticated using((owner_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id)) or (visibility='shared' and app_private.is_conversation_member(conversation_id)));
create policy "Members upload their own conversation documents" on public.conversation_documents for insert to authenticated with check(owner_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id));
create policy "Owners update their conversation documents" on public.conversation_documents for update to authenticated using(owner_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id)) with check(owner_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id));
create policy "Owners delete their conversation documents" on public.conversation_documents for delete to authenticated using(owner_id=(select auth.uid()) and app_private.is_conversation_member(conversation_id));
create policy "Direct chat members read private reply context" on public.private_reply_contexts for select to authenticated using(app_private.is_conversation_member(direct_conversation_id));
create policy "Sender inserts private reply context" on public.private_reply_contexts for insert to authenticated with check(sender_id=(select auth.uid()) and app_private.is_conversation_member(direct_conversation_id) and app_private.is_conversation_member(source_conversation_id) and exists(select 1 from public.chat_messages dm where dm.id=direct_message_id and dm.conversation_id=direct_conversation_id and dm.sender_id=(select auth.uid())) and exists(select 1 from public.chat_messages sm where sm.id=source_message_id and sm.conversation_id=source_conversation_id and sm.sender_id=quoted_sender_id and sm.deleted_at is null));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('conversation-documents','conversation-documents',false,26214400,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=26214400,allowed_mime_types=excluded.allowed_mime_types;
create policy "Conversation document owners and shared members read files" on storage.objects for select to authenticated using(bucket_id='conversation-documents' and exists(select 1 from public.conversation_documents d where d.storage_path=name and app_private.is_conversation_member(d.conversation_id) and (d.owner_id=(select auth.uid()) or d.visibility='shared')));
create policy "Conversation members upload own document files" on storage.objects for insert to authenticated with check(bucket_id='conversation-documents' and (storage.foldername(name))[2]=(select auth.uid())::text and app_private.is_conversation_member(((storage.foldername(name))[1])::uuid));
create policy "Owners update own conversation document files" on storage.objects for update to authenticated using(bucket_id='conversation-documents' and owner_id=(select auth.uid())::text and (storage.foldername(name))[2]=(select auth.uid())::text) with check(bucket_id='conversation-documents' and owner_id=(select auth.uid())::text and (storage.foldername(name))[2]=(select auth.uid())::text);
create policy "Owners delete own conversation document files" on storage.objects for delete to authenticated using(bucket_id='conversation-documents' and owner_id=(select auth.uid())::text and (storage.foldername(name))[2]=(select auth.uid())::text);
